package generator

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/spf13/cobra"
)

func TestCleanMarkdown(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name  string
		input string
		want  string
	}{
		{
			"title and footer",
			"---\n# devtui demo\nDemo text\nlower text\n\n###### Auto generated by spf13/cobra on 1-Jan-2026",
			"---\nDemo text\nlower text\n",
		},
		{
			"see also ends at a section",
			"intro\n### SEE ALSO\n\n* [devtui](devtui.md)\n### Options\nafter",
			"intro\n### Options\nafter",
		},
		{
			"see also ends at a command",
			"intro\n### SEE ALSO\n* [devtui](devtui.md)\n## devtui demo sub\nafter",
			"intro\n## devtui demo sub\nafter",
		},
		{
			"see also ends at the subcommand separator",
			"intro\n### SEE ALSO\n* [devtui](devtui.md)\nSee the website\n---\n\n## devtui demo sub",
			"intro\n---\n\n## devtui demo sub",
		},
		{
			"examples are trimmed",
			"### Examples\n```\n  devtui demo\n\n\tDevtui demo -x\n```\n  between\n```\n  devtui demo -y\n```",
			"### Examples\n```bash\ndevtui demo\nDevtui demo -x\n```\n  between\n```bash\ndevtui demo -y\n```",
		},
		{
			"synopsis keeps indentation",
			"### Synopsis\n```\n  devtui demo [flags]\ndevtui demo\n```",
			"### Synopsis\n```bash\n  devtui demo [flags]\ndevtui demo\n```",
		},
		{
			"options have no language",
			"### Options\n```\n  -h, --help\n```\nText between\n```\n  -v\n```",
			"### Options\n```\n  -h, --help\n```\nText between\n```\n  -v\n```",
		},
		{
			"code before any section",
			"```\n  plain\n```",
			"```\n  plain\n```",
		},
		{
			"code after synopsis section",
			"### Usage\n```\n  usage\n```",
			"### Usage\n```\n  usage\n```",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			if got := cleanMarkdown(tt.input); got != tt.want {
				t.Errorf("cleanMarkdown(%q) = %q, want %q", tt.input, got, tt.want)
			}
		})
	}
}

func newCommand(use string) *cobra.Command {
	return &cobra.Command{Use: use, Short: use + " command", Run: func(*cobra.Command, []string) {}}
}

func TestGenerateMarkdownForCommand(t *testing.T) {
	t.Parallel()

	root := newCommand("devtui")
	demo := newCommand("demo")
	demo.AddCommand(newCommand("decode"), newCommand("help"), newCommand("verify"))
	root.AddCommand(demo)

	dir := t.TempDir()
	generateMarkdownForCommand(demo, dir)

	content, err := os.ReadFile(filepath.Join(dir, "demo.md"))
	if err != nil {
		t.Fatal(err)
	}
	got := string(content)

	if !strings.HasPrefix(got, "---\ntitle: demo\nparent: CLI\n---\n\n## devtui demo\n") {
		t.Errorf("expected front matter and title, got %q", got)
	}
	for _, want := range []string{"\n---\n\n## devtui demo decode\n", "\n---\n\n## devtui demo verify\n"} {
		if !strings.Contains(got, want) {
			t.Errorf("expected %q in output, got %q", want, got)
		}
	}
	for _, unwanted := range []string{"## devtui demo help", "SEE ALSO", "Auto generated"} {
		if strings.Contains(got, unwanted) {
			t.Errorf("expected no %q in output, got %q", unwanted, got)
		}
	}
}

func TestGenerateCLIDocumentation(t *testing.T) {
	t.Parallel()

	root := newCommand("devtui")
	root.AddCommand(newCommand("alpha"), newCommand("version"), newCommand("zulu"))

	dir := t.TempDir()
	GenerateCLIDocumentation(root, dir)

	tests := []struct {
		file string
		want bool
	}{
		{"alpha.md", true},
		{"version.md", false},
		{"zulu.md", true},
	}
	for _, tt := range tests {
		_, err := os.Stat(filepath.Join(dir, tt.file))
		if got := err == nil; got != tt.want {
			t.Errorf("%s exists = %v, want %v", tt.file, got, tt.want)
		}
	}
}
